// ---- дайындау ----
const perSection = {};
export const FORMULAS = LIST.map((f) => {
  perSection[f.s] = (perSection[f.s] || 0) + 1;
  const vars = f.v
    ? f.v.split(';').map((x) => {
        const [sym, meaning, unit] = x.split('|');
        return { sym: sym.trim(), meaning: (meaning || '').trim(), unit: (unit || '').trim() };
      })
    : [];
  return { id: `${f.s}-${perSection[f.s]}`, s: f.s, g: f.g, name: f.name, tex: f.tex, vars, note: f.note, def: DEF[f.name] || '' };
});
export const FORMULA = Object.fromEntries(FORMULAS.map((f) => [f.id, f]));

// Ойындарға арналған жеңіл нұсқа (TeX қалпында, браузерде KaTeX салады).
export const formulasForGames = () =>
  FORMULAS.map((f) => ({ id: f.id, s: f.s, g: f.g, n: f.name, t: f.tex, v: f.vars.map((x) => [x.sym, x.meaning, x.unit]) }));
